tart_up\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/StartUpStages\",\"description\":\"Start-up cost at different stages of the thermal cycle (hot, warm, cold).\"}},\"required\":[\"minimum_energy_offer\",\"start_up\",\"shut_down\",\"incremental_offer_curves\",\"decremental_offer_curves\",\"ancillary_service_offers\"],\"title\":\"MarketBidCost\",\"type\":\"object\"},\"MarketBidTimeSeriesCost\":{\"description\":\"Cost representation for time-varying market bids of energy and ancillary services. The static counterpart is MarketBidCost.\",\"properties\":{\"ancillary_service_offers\":{\"description\":\"IDs of the ancillary service components that this bid offers into.\",\"items\":{\"type\":\"integer\"},\"type\":\"array\"},\"cost_type\":{\"const\":\"MARKET_BID_TIME_SERIES\",\"default\":\"MARKET_BID_TIME_SERIES\",\"type\":\"string\"},\"curve_style\":{\"default\":0,\"description\":\"Curve-clearing style for the bid: 0 = CURVE (ordinary divisible price-setting curve, default); 1 = FIXED (clears as one indivisible all-or-nothing package over its period); 2 = VARIABLE (divisible quantity, block-priced, cannot set the settlement-point price). Corresponds to ERCOT's DAM PriceCurve curveStyle field (CURVE/FIXED/VARIABLE). A non-zero value is mutually exclusive with incremental_slope/decremental_slope.\",\"enum\":[0,1,2],\"type\":\"integer\"},\"decremental_offer_curves\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/CostCurve\",\"description\":\"Buy offer curves whose value curve is a time-series-backed piecewise incremental curve. Only the TIME_SERIES_INCREMENTAL variant is admissible here; any other variant is rejected by the consuming constructor.\"},\"decremental_slope\":{\"default\":false,\"description\":\"Linear-interpolation flag for the decremental offer curves; false (default) is the step interpretation. Mutually exclusive with block groups on the same curve.\",\"type\":\"boolean\"},\"incremental_offer_curves\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/CostCurve\",\"description\":\"Sell offer curves whose value curve is a time-series-backed piecewise incremental curve. Only the TIME_SERIES_INCREMENTAL variant is admissible here; any other variant is rejected by the consuming constructor.\"},\"incremental_slope\":{\"default\":false,\"description\":\"Linear-interpolation flag for the incremental offer curves; false (default) is the step interpretation. Mutually exclusive with block groups on the same curve.\",\"type\":\"boolean\"},\"minimum_energy_offer\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/TimeSeriesInputOutputCurve\",\"description\":\"Minimum-energy offer: cost to operate at minimum stable level, in \$/MWh at the curve's minimum power, stored as submitted. \$/h sources convert at parse (MEO = no-load cost / P_min). Time-series-backed linear curve; only the TIME_SERIES_LINEAR function-data variant is admissible here — the consuming constructor rejects any other.\"},\"shut_down\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/TimeSeriesInputOutputCurve\",\"description\":\"Shut-down cost as a time-series-backed linear curve. Only the TIME_SERIES_LINEAR function-data variant is admissible here; the consuming constructor rejects any other.\"},\"start_up_association_id\":{\"description\":\"Store-minted id of a time series of three-stage (hot, warm, cold) start-up costs.\",\"type\":\"integer\"}},\"required\":[\"cost_type\",\"minimum_energy_offer\",\"start_up_association_id\",\"shut_down\",\"incremental_offer_curves\",\"decremental_offer_curves\",\"ancillary_service_offers\"],\"title\":\"MarketBidTimeSeriesCost\",\"type\":\"object\"},\"MassUnit\":{\"description\":\"Mass unit an emission quantity is reported in: kilograms, pounds, short tons (2000 lb), or metric tons (1000 kg).\",\"enum\":[\"KG\",\"LB\",\"SHORT_TON\",\"METRIC_TON\"],\"title\":\"MassUnit\",\"type\":\"string\"},\"PiecewiseLinearData\":{\"description\":\"Data for a piecewise linear function defined by (x, y) points and interpolated linearly between consecutive ones. The y values are absolute values at each x, not per-segment slopes; use `PiecewiseStepData` when the data gives per-segment rates. Points run in ascending x order, and two of them define one segment.\",\"properties\":{\"function_type\":{\"const\":\"PIECEWISE_LINEAR\",\"default\":\"PIECEWISE_LINEAR\",\"type\":\"string\"},\"points\":{\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/XY_Coords\"},\"type\":\"array\"}},\"required\":[\"points\",\"function_type\"],\"title\":\"PiecewiseLinearData\",\"type\":\"object\"},\"PiecewiseStepData\":{\"description\":\"Data for a step function, constant on each segment, defined by the x coordinates of the segment endpoints and one y value per segment. The y values are per-segment rates, not absolute values; use `PiecewiseLinearData` when the data gives a value at each point. `x_coords` ascends and holds at least two entries, and `y_coords` holds exactly one fewer.\",\"properties\":{\"function_type\":{\"const\":\"PIECEWISE_STEP\",\"default\":\"PIECEWISE_STEP\",\"type\":\"string\"},\"x_coords\":{\"items\":{\"type\":\"number\"},\"type\":\"array\"},\"y_coords\":{\"items\":{\"type\":\"number\"},\"type\":\"array\"}},\"required\":[\"x_coords\",\"y_coords\",\"function_type\"],\"title\":\"PiecewiseStepData\",\"type\":\"object\"},\"PollutantType\":{\"description\":\"Pollutant an emission rate is reported for, spanning greenhouse gases (`CO2`, `CO2E`, `CH4`, `N2O`), criteria pollutants (`NOX`, `SO2`, `CO`, `VOC`, `PM25`, `PM10`), and toxics (`HG`, `HAP`), with `CUSTOM` for a user-defined pollutant.\",\"enum\":[\"CO2\",\"CO2E\",\"CH4\",\"N2O\",\"NOX\",\"SO2\",\"CO\",\"VOC\",\"PM25\",\"PM10\",\"HG\",\"HAP\",\"CUSTOM\"],\"title\":\"PollutantType\",\"type\":\"string\"},\"PrimeMovers\":{\"description\":\"Prime mover of a generating unit — the engine, turbine, water wheel, or similar machine that drives the generator — using the code set from the EIA Form 923 instructions. `PVe` is photovoltaic, spelled that way so it does not collide with the `PV` bus type.\",\"enum\":[\"BA\",\"BT\",\"CA\",\"CC\",\"CE\",\"CP\",\"CS\",\"CT\",\"ES\",\"FC\",\"FW\",\"GT\",\"HA\",\"HB\",\"HK\",\"HY\",\"IC\",\"PS\",\"OT\",\"ST\",\"PVe\",\"WT\",\"WS\"],\"title\":\"PrimeMovers\",\"type\":\"string\"},\"ProductionVariableCostCurve\":{\"description\":\"Variable production cost of a device, selected by `variable_cost_type` between a curve denominated directly in currency (`COST`) and one denominated in fuel with a separate fuel price (`FUEL`).\",\"discriminator\":{\"mapping\":{\"COST\":\"#/components/schemas/CostCurve\",\"FUEL\":\"#/components/schemas/FuelCurve\"},\"propertyName\":\"variable_cost_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/CostCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/FuelCurve\"}],\"title\":\"ProductionVariableCostCurve\",\"type\":\"object\"},\"QuadraticFunctionData\":{\"description\":\"Data for a quadratic function `f(x) = quadratic_term * x^2 + proportional_term * x + constant_term`. A non-negative `quadratic_term` makes the function convex.\",\"properties\":{\"constant_term\":{\"type\":\"number\"},\"function_type\":{\"const\":\"QUADRATIC\",\"default\":\"QUADRATIC\",\"type\":\"string\"},\"proportional_term\":{\"type\":\"number\"},\"quadratic_term\":{\"type\":\"number\"}},\"required\":[\"quadratic_term\",\"proportional_term\",\"constant_term\",\"function_type\"],\"title\":\"QuadraticFunctionData\",\"type\":\"object\"},\"RenewableGenerationCost\":{\"description\":\"Cost representation for renewable generation units\",\"properties\":{\"cost_type\":{\"const\":\"RENEWABLE\",\"default\":\"RENEWABLE\",\"type\":\"string\"},\"curtailment_cost\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/CostCurve\",\"default\":{\"value_curve\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"constant_term\":0,\"function_type\":\"LINEAR\",\"proportional_term\":0}},\"variable_cost_type\":\"COST\",\"vom_cost\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"constant_term\":0,\"function_type\":\"LINEAR\",\"proportional_term\":0}}}},\"fixed\":{\"default\":0.0,\"type\":\"number\"},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/CostCurve\"}},\"required\":[\"variable_operation_cost\"],\"title\":\"RenewableGenerationCost\",\"type\":\"object\"},\"ReservoirLocation\":{\"description\":\"Position of a hydro reservoir relative to its turbine: `HEAD` upstream of the turbine, typically at higher elevation; `TAIL` downstream, at lower or equal elevation.\",\"enum\":[\"HEAD\",\"TAIL\"],\"title\":\"ReservoirLocation\",\"type\":\"string\"},\"ShuntAdmittanceUnitBasis\":{\"description\":\"Subset of AdmittanceUnitBasis for fixed and switched shunts: omits COMPONENT_BASE because a shunt has no device MVA rating to per-unitize against. NATURAL_UNITS: physical siemens. COMPONENT_MVAR: reactive power at unity voltage (Mvar for susceptance, MW for conductance) — PSS/E RAW native for shunts.\",\"enum\":[\"NATURAL_UNITS\",\"COMPONENT_MVAR\"],\"title\":\"ShuntAdmittanceUnitBasis\",\"type\":\"string\"},\"StartUpShutDown\":{\"description\":\"A pair of values, one for the start-up phase and one for the shut-down phase of a unit's cycle.\",\"properties\":{\"shutdown\":{\"title\":\"ShutDown\",\"type\":\"number\"},\"startup\":{\"title\":\"StartUp\",\"type\":\"number\"}},\"title\":\"StartUpShutDown\",\"type\":\"object\"},\"StartUpStages\":{\"description\":\"A triple of values, one for each stage of a thermal unit's start-up: `hot`, `warm`, and `cold`.\",\"properties\":{\"cold\":{\"type\":\"number\"},\"hot\":{\"type\":\"number\"},\"startup_stages_type\":{\"const\":\"STAGES\",\"default\":\"STAGES\",\"type\":\"string\"},\"warm\":{\"type\":\"number\"}},\"required\":[\"hot\",\"warm\",\"cold\"],\"title\":\"StartUpStages\",\"type\":\"object\"},\"StorageCost\":{\"description\":\"Cost representation for storage units\",\"properties\":{\"charge_variable_cost\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/CostCurve\"},\"cost_type\":{\"const\":\"STORAGE\",\"default\":\"STORAGE\",\"type\":\"string\"},\"discharge_variable_cost\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/CostCurve\"},\"energy_shortage_cost\":{\"default\":0.0,\"type\":\"number\"},\"energy_surplus_cost\":{\"default\":0.0,\"type\":\"number\"},\"fixed\":{\"default\":0.0,\"type\":\"number\"},\"shut_down\":{\"default\":0.0,\"type\":\"number\"},\"start_up\":{\"default\":0.0,\"oneOf\":[{\"type\":\"number\"},{\"properties\":{\"charge\":{\"type\":\"number\"},\"discharge\":{\"type\":\"number\"}},\"type\":\"object\"}]}},\"required\":[\"fixed\",\"start_up\",\"shut_down\"],\"title\":\"StorageCost\",\"type\":\"object\"},\"StorageTech\":{\"description\":\"defines the storage technology used in an energy Storage system, based on the options in EIA form 923.\",\"enum\":[\"PTES\",\"LIB\",\"LAB\",\"FLWB\",\"SIB\",\"ZIB\",\"HGS\",\"LAES\",\"OTHER_CHEM\",\"OTHER_MECH\",\"OTHER_THERM\"],\"title\":\"StorageTech\",\"type\":\"string\"},\"ThermalFuels\":{\"description\":\"Thermal fuels that reflect options in the EIA annual energy review.\",\"enum\":[\"ANTHRACITE_COAL\",\"BITUMINOUS_COAL\",\"LIGNITE_COAL\",\"SUBBITUMINOUS_COAL\",\"WASTE_COAL\",\"REFINED_COAL\",\"SYNTHESIS_GAS_COAL\",\"DISTILLATE_FUEL_OIL\",\"JET_FUEL\",\"KEROSENE\",\"PETROLEUM_COKE\",\"RESIDUAL_FUEL_OIL\",\"PROPANE\",\"SYNTHESIS_GAS_PETROLEUM_COKE\",\"WASTE_OIL\",\"BLAST_FURNACE_GAS\",\"NATURAL_GAS\",\"OTHER_GAS\",\"AG_BYPRODUCT\",\"MUNICIPAL_WASTE\",\"OTHER_BIOMASS_SOLIDS\",\"WOOD_WASTE_SOLIDS\",\"OTHER_BIOMASS_LIQUIDS\",\"SLUDGE_WASTE\",\"BLACK_LIQUOR\",\"WOOD_WASTE_LIQUIDS\",\"LANDFILL_GAS\",\"OTHER_BIOMASS_GAS\",\"NUCLEAR\",\"WASTE_HEAT\",\"TIRE_DERIVED_FUEL\",\"COAL\",\"GEOTHERMAL\",\"OTHER\"],\"title\":\"ThermalFuels\",\"type\":\"string\"},\"ThermalGenerationCost\":{\"description\":\"Cost representation for thermal generation units\",\"properties\":{\"cost_type\":{\"const\":\"THERMAL\",\"default\":\"THERMAL\",\"type\":\"string\"},\"fixed\":{\"description\":\"Fixed cost of keeping the unit online. For some cost represenations this field can be duplicative\",\"type\":\"number\"},\"shut_down\":{\"description\":\"Cost to turn the unit off\",\"type\":\"number\"},\"start_up\":{\"description\":\"Start-up cost can take linear or multi-stage cost\",\"discriminator\":{\"mapping\":{\"STAGES\":\"#/components/schemas/StartUpStages\"},\"propertyName\":\"startup_stages_type\"},\"oneOf\":[{\"type\":\"number\"},{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/StartUpStages\"}]},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/ProductionVariableCostCurve\"}},\"required\":[\"variable_operation_cost\",\"fixed\",\"start_up\",\"shut_down\"],\"title\":\"ThermalGenerationCost\",\"type\":\"object\"},\"TimeSeriesAverageRateCurve\":{\"description\":\"A time-series-backed average rate curve. The static counterpart is AverageRateCurve.\",\"properties\":{\"curve_type\":{\"const\":\"TIME_SERIES_AVERAGE_RATE\",\"default\":\"TIME_SERIES_AVERAGE_RATE\",\"type\":\"string\"},\"function_data\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/FunctionData\",\"description\":\"Only TIME_SERIES_LINEAR or TIME_SERIES_PIECEWISE_STEP is admissible here; all other FunctionData variants, static or time-series-backed, are rejected by the consuming constructor.\"},\"initial_input_association_id\":{\"description\":\"Store-minted id of the time series supplying the initial input value, or null.\",\"type\":[\"integer\",\"null\"]},\"input_at_zero_association_id\":{\"description\":\"Store-minted id of the time series supplying the input at zero output, or null.\",\"type\":[\"integer\",\"null\"]}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"TimeSeriesAverageRateCurve\",\"type\":\"object\"},\"TimeSeriesIncrementalCurve\":{\"description\":\"A time-series-backed incremental curve. The static counterpart is IncrementalCurve.\",\"properties\":{\"curve_type\":{\"const\":\"TIME_SERIES_INCREMENTAL\",\"default\":\"TIME_SERIES_INCREMENTAL\",\"type\":\"string\"},\"function_data\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/FunctionData\",\"description\":\"Only TIME_SERIES_LINEAR or TIME_SERIES_PIECEWISE_STEP is admissible here; all other FunctionData variants, static or time-series-backed, are rejected by the consuming constructor.\"},\"initial_input_association_id\":{\"description\":\"Store-minted id of the time series supplying the initial input value, or null.\",\"type\":[\"integer\",\"null\"]},\"input_at_zero_association_id\":{\"description\":\"Store-minted id of the time series supplying the input at zero output, or null.\",\"type\":[\"integer\",\"null\"]}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"TimeSeriesIncrementalCurve\",\"type\":\"object\"},\"TimeSeriesInputOutputCurve\":{\"description\":\"A time-series-backed input-output curve. The static counterpart is InputOutputCurve.\",\"properties\":{\"curve_type\":{\"const\":\"TIME_SERIES_INPUT_OUTPUT\",\"default\":\"TIME_SERIES_INPUT_OUTPUT\",\"type\":\"string\"},\"function_data\":{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/FunctionData\",\"description\":\"Only TIME_SERIES_LINEAR, TIME_SERIES_QUADRATIC, or TIME_SERIES_PIECEWISE_LINEAR is admissible here; the static variants and TIME_SERIES_PIECEWISE_STEP are invalid and rejected by the consuming constructor.\"},\"input_at_zero\":{\"description\":\"Optional explicit input value at zero output. A number here, unlike the incremental and average-rate variants, where it is a time series reference.\",\"type\":[\"number\",\"null\"]}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"TimeSeriesInputOutputCurve\",\"type\":\"object\"},\"TimeSeriesLinearFunctionData\":{\"description\":\"Time-series-backed variant of `LinearFunctionData`. In place of inline coefficients it carries `association_id`, referencing a stored series that supplies them at each step; use it when the coefficients change over time.\",\"properties\":{\"association_id\":{\"description\":\"Store-minted id of the time series association whose values supply this function data over time. Resolved against the accompanying time series store on read; minted by that store and meaningful only against it, never assigned by a document producer.\",\"type\":\"integer\"},\"function_type\":{\"const\":\"TIME_SERIES_LINEAR\",\"default\":\"TIME_SERIES_LINEAR\",\"type\":\"string\"}},\"required\":[\"function_type\",\"association_id\"],\"title\":\"TimeSeriesLinearFunctionData\",\"type\":\"object\"},\"TimeSeriesPiecewiseLinearData\":{\"description\":\"Time-series-backed variant of `PiecewiseLinearData`. In place of an inline point table it carries `association_id`, referencing a stored series that supplies one at each step; use it when the points change over time.\",\"properties\":{\"association_id\":{\"description\":\"Store-minted id of the time series association whose values supply this function data over time. Resolved against the accompanying time series store on read; minted by that store and meaningful only against it, never assigned by a document producer.\",\"type\":\"integer\"},\"function_type\":{\"const\":\"TIME_SERIES_PIECEWISE_LINEAR\",\"default\":\"TIME_SERIES_PIECEWISE_LINEAR\",\"type\":\"string\"}},\"required\":[\"function_type\",\"association_id\"],\"title\":\"TimeSeriesPiecewiseLinearData\",\"type\":\"object\"},\"TimeSeriesPiecewiseStepData\":{\"description\":\"Time-series-backed variant of `PiecewiseStepData`. In place of inline coordinate vectors it carries `association_id`, referencing a stored series that supplies them at each step; use it when the segments change over time.\",\"properties\":{\"association_id\":{\"description\":\"Store-minted id of the time series association whose values supply this function data over time. Resolved against the accompanying time series store on read; minted by that store and meaningful only against it, never assigned by a document producer.\",\"type\":\"integer\"},\"function_type\":{\"const\":\"TIME_SERIES_PIECEWISE_STEP\",\"default\":\"TIME_SERIES_PIECEWISE_STEP\",\"type\":\"string\"}},\"required\":[\"function_type\",\"association_id\"],\"title\":\"TimeSeriesPiecewiseStepData\",\"type\":\"object\"},\"TimeSeriesQuadraticFunctionData\":{\"description\":\"Time-series-backed variant of `QuadraticFunctionData`. In place of inline coefficients it carries `association_id`, referencing a stored series that supplies them at each step; use it when the coefficients change over time.\",\"properties\":{\"association_id\":{\"description\":\"Store-minted id of the time series association whose values supply this function data over time. Resolved against the accompanying time series store on read; minted by that store and meaningful only against it, never assigned by a document producer.\",\"type\":\"integer\"},\"function_type\":{\"const\":\"TIME_SERIES_QUADRATIC\",\"default\":\"TIME_SERIES_QUADRATIC\",\"type\":\"string\"}},\"required\":[\"function_type\",\"association_id\"],\"title\":\"TimeSeriesQuadraticFunctionData\",\"type\":\"object\"},\"TurbinePump\":{\"description\":\"A pair of values, one for the turbine (generating) mode and one for the pump (charging) mode of a pumped hydro unit.\",\"properties\":{\"pump\":{\"type\":\"number\"},\"turbine\":{\"type\":\"number\"}},\"required\":[\"turbine\",\"pump\"],\"title\":\"TurbinePump\",\"type\":\"object\"},\"TwoTerminalLoss\":{\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"constant_term\":0,\"function_type\":\"LINEAR\",\"proportional_term\":0}},\"description\":\"Loss model of a two-terminal HVDC line as a function of flow, selected by `curve_type`. It accepts a linear model with a constant loss and a proportional loss rate (MW of loss per MW of flow), or a piecewise model giving different proportional losses on different flow segments.\",\"discriminator\":{\"mapping\":{\"INCREMENTAL\":\"#/components/schemas/IncrementalCurve\",\"INPUT_OUTPUT\":\"#/components/schemas/InputOutputCurve\"},\"propertyName\":\"curve_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/InputOutputCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/IncrementalCurve\"}],\"title\":\"TwoTerminalLoss\",\"type\":\"object\"},\"UnitSystem\":{\"description\":\"Unit basis a stored value is expressed in. COMPONENT_BASE: per-unit against a base the component records itself. NATURAL_UNITS: the quantity's own physical unit. No system-wide option: a value per-unitized against a shared base records that base on the component and rides as COMPONENT_BASE. Used in three scopes, each read against its own record rather than a document-wide table: a component's own `power_units` (against that component's `base_power`), a cost payload's own `power_units` (e.g. `CostCurve`, against the owning component's `base_power`), and a time series association's own `unit_system` (governing only that one series).\",\"enum\":[\"COMPONENT_BASE\",\"NATURAL_UNITS\"],\"title\":\"UnitSystem\",\"type\":\"string\"},\"ValueCurve\":{\"description\":\"A cost or fuel curve: function data plus a declaration of how to read its y axis. `INPUT_OUTPUT` reads y as the total `f(x)`, `INCREMENTAL` as the marginal rate `f'(x)`, and `AVERAGE_RATE` as the average `f(x)/x`; the three can express the same underlying function and are inter-convertible given `initial_input`. The `TIME_SERIES_*` variants are the time-varying equivalents. Which form to use follows the data source: bid stacks are incremental, total cost tables input-output, efficiency tables average rate.\",\"discriminator\":{\"mapping\":{\"AVERAGE_RATE\":\"#/components/schemas/AverageRateCurve\",\"INCREMENTAL\":\"#/components/schemas/IncrementalCurve\",\"INPUT_OUTPUT\":\"#/components/schemas/InputOutputCurve\",\"TIME_SERIES_AVERAGE_RATE\":\"#/components/schemas/TimeSeriesAverageRateCurve\",\"TIME_SERIES_INCREMENTAL\":\"#/components/schemas/TimeSeriesIncrementalCurve\",\"TIME_SERIES_INPUT_OUTPUT\":\"#/components/schemas/TimeSeriesInputOutputCurve\"},\"propertyName\":\"curve_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/InputOutputCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/IncrementalCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/AverageRateCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/TimeSeriesInputOutputCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/TimeSeriesIncrementalCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/root-66da9c296f8dc2d2bc25.json#/components/schemas/TimeSeriesAverageRateCurve\"}],\"title\":\"ValueCurve\",\"type\":\"object\"},\"XY_Coords\":{\"description\":\"A single point, given as its `x` and `y` coordinates.\",\"properties\":{\"x\":{\"type\":\"number\"},\"y\":{\"type\":\"number\"}},\"required\":[\"x\",\"y\"],\"title\":\"XY_Coords\",\"type\":\"object\"}}},\"info\":{\"description\":\"Shared types for the Sienna power systems ecosystem: curves, enums, helpers (MinMax, UpDown, CostCurve, etc.)\",\"title\":\"PowerCoreOpenAPIModels\",\"version\":\"1.0.0\"},\"openapi\":\"3.1.0\",\"paths\":{}}"),
]
